-- Migration 0102: Batch 1 of the exercise-library enrichment — PULL
--
-- Roadmap X-35 / X-38. The `pull` axis is one of six the planner biases toward
-- (R551) and the radar displays, but the library held exactly one genuine
-- bodyweight pulling movement (`inverted-row-table`), and `pull_up_bar` — an
-- onboarding option — had five exercises. A user whose weakest axis was pull got
-- biased toward work that did not exist, so the axis never moved. It is also why
-- the fitness assessment renders pull as "not measured".
--
-- 14 exercises: 7 need nothing or a band (so the axis becomes trainable for
-- everyone), 3 use a pull-up bar, 4 use gym machines. Four more were drafted and
-- dropped — band-pull-apart, band-face-pull, chin-up and dead-hang already exist. Machine equipment is also
-- selectable in ALL_EQUIPMENT, so a home owner unlocks them without gym_today.
--
-- Every row carries its loads_* injury tags — R563 filters on them, and a row
-- without them silently bypasses the safety filter.

INSERT INTO exercises
  (id, slug, name, category, primary_muscles_json, secondary_muscles_json,
   tags_json, equipment_required_json, instructions_json, metrics_json,
   is_active, visibility, created_at_ms, updated_at_ms)
