('ex_pull_band_seated_row','band-seated-row','Band Seated Row','strength','["upper_back", "rhomboids", "lats"]','["biceps"]','["strength", "pull", "upper_body", "resistance_bands", "floor", "quiet", "low_impact"]','["resistance_bands"]','{"steps": ["Sit on the floor, legs straight, band looped around both feet.", "Sit tall with a long spine, holding one end in each hand.", "Pull your hands to your waist, elbows close to your body.", "Straighten the arms slowly."], "cues": ["Chest up throughout", "Do not lean back to move the band", "\ud83d\udca1 Bend the knees slightly if your hamstrings are tight"]}','{"supports": ["reps", "sets", "tempo"]}',1,'global',1789300000000,1789300000000),
