('ex_pull_towel_row','towel-door-row','Towel Row (Door)','strength','["lats", "upper_back", "rhomboids"]','["biceps", "core"]','["strength", "pull", "upper_body", "bodyweight", "no_floor", "low_impact"]','["none"]','{"steps": ["Loop a towel around a secure door handle on a closed, latched door.", "Hold one end in each hand and walk your feet towards the door, leaning back.", "Pull your chest towards the handle.", "Lower under control."], "cues": ["Test the door holds your weight first", "The further your feet, the harder it gets", "\ud83d\udca1 Keep the hips in line \u2014 do not let them sag"]}','{"supports": ["reps", "sets"]}',1,'global',1789300000000,1789300000000),
